/// <summary>
///     The <c>NDX_KBVErrorTypes</c> class is the extension of table <c>common</c>
/// </summary>
public class NDX_KBVErrorTypes extends common
{
}

Method.Source:
/// <summary>
///    AVA <c>checkErrorType</c> method.
/// </summary>
/// <param name="_startline">
///    <c>int</c> as type
/// </param>
/// <param name="_endline">
///    <c>int</c> as type
/// </param>
/// <returns>
///    <c>NDX_KBVErrors</c> as return value
/// </returns>
static NDX_KBVErrors checkErrorType(int _startline = 1, int _endline = infologLine())
{
    int                 counter;
    NDX_KBVErrorTypes   errorTypes;
    NDX_KBVErrors       ndx_KBVErrors;

    ndx_KBVErrors = NDX_KBVErrors::undefined;

    while select errorTypes
    order by errorTypes.KBVError asc
    where errorTypes.KBVError != NDX_KBVErrors::undefined
    {
        for(counter = _startline; counter <= _endline; counter++)
        {
            if(Infolog.text(counter) like errorTypes.criterion)
            {
                ndx_KBVErrors = errorTypes.KBVError;
                break;
            }
        }
        if(ndx_KBVErrors != NDX_KBVErrors::undefined)
        {
            break;
        }

    }
    return ndx_KBVErrors;
}
